def the_firstling(case, data):
    """F6 — Deut 15:19-20 — CONSECRATED FROM THE WOMB (consecrated_firstborn REUSED by CALL to korach and ordinances), SANCTIFIED FOR ITS VALUE against Leviticus 27:26 (temurah.consecrate by CALL — the DISAGREES row resolved as data); THE LINE firstling_law_declared writing firstling_sanctification_commanded (a STATUS) and firstling_work_and_shearing_barred (a BLOCK); THE FIRSTLING'S YEAR A CLOCK DATUM with its two-day edge; the blemished's thirty days; the tending term 'given only to the Sages'; before the LORD at the place — holy_things_in_the_gates_barred REUSED"""
    del P_[:]
    ask = case['ask']
    if ask == 'consecrated_from_the_womb':
        ink('15:19', '"EVERY FIRSTLING that is BORN of your herd and of your flock, THE MALE, you shall sanctify" — "firstling" three tokens here of the book\'s eight %s; Exodus 13:2 "sanctify to Me every firstborn, the opener of every womb" %s; 34:19 "every opener of the womb is Mine … you shall sanctify the males" %s; Numbers 18:17 "the firstling of an ox … you shall not redeem, they are holy" %s' % ([(s, x) for s, x, _ in LEMT('1060', books=DT) if s.startswith('Deut 15')], words('Exod', 13, 2)[:7], words('Exod', 34, 19)[:6], words('Num', 18, 17)[:10]))
        move('the Sifrei 124:1 (read whole at the reading); Bekhorot 19a:4, 41b:8, 42a:11 (read whole at the docket); cold_run_korach (CALL) — KO.the_gifts(opens_the_womb) = %s (fx %s), (clean_firstborn) = %s; cold_run_ordinances (CALL) — OR.firstling(eighth_and_onward) = %s, (two_seats_one_timer) = %s; the one database: consecrated_firstborn anywhere on the tape\'s world NONE (the case worlds\' own)' % (str(V(KO_WOMB))[:60], KO_WOMB[1], str(V(KO_CLEAN))[:50], V(OR_EIGHTH), V(OR_TIMER)), "CONSECRATED FROM THE WOMB — consecrated_firstborn REUSED BY CALL: the consecration is Exodus 13:2's and Numbers 18:17's (the status 'written at birth' — korach.the_gifts(opens_the_womb) writes it; ordinances.firstling the eighth day and the seven with its mother), NOT THIS VERSE'S: 'the male' the detail of Exodus 13:2 (Bekhorot 19a:4; the sex's edge 41b:8, 42a:11); its year and the blemished from 'every' (124:1 — 'every firstling': within its year and after, unblemished and blemished)")
        dat('consecrated_firstborn REUSED at the case (the exam\'s firstling written on at its birth by the korach cell\'s own effect — never on the tape); the exam\'s person the firstling male born of the herd — consecrated from the womb')
        return out("consecrated from the womb (15:19) — the consecration Exodus 13:2's and Numbers 18:17's by CALL (korach.the_gifts opens_the_womb — consecrated_firstborn the status written at birth; ordinances.firstling the eighth day), not this verse's; 'the male' Exodus 13:2's detail (Bekhorot 19a:4): the firstling male born of the herd consecrated from the womb", ['consecrated_firstborn'])
    if ask == 'the_sanctify_for_value':
        ink('15:19', '"the male YOU SHALL SANCTIFY to the LORD your God" — "the male you shall sanctify" %s (one seat); Leviticus 27:26 "but a firstling … NO MAN SHALL SANCTIFY IT; whether ox or sheep, it is the LORD\'s" %s; the sanctify-verb\'s sixteen seats hold 27:26 %s' % (P('הזכר', 'תקדיש'), words('Lev', 27, 26), 'Lev 27:26' in U('תקדיש', 'יקדיש', 'הקדיש', 'תקדישו', 'יקדישו')))
        move('the Sifrei 124:4 (read whole at the reading); Mishnah Arakhin 8:7 (inside the spine and at the docket); Arakhin 29a:20, Nazir 4b:11 (read whole at the docket); cold_run_temurah (CALL) — TM.consecrate(firstborn_for_value) = %s (fx %s), TM.consecrate(firstborn) = %s' % (V(TM_FBV), TM_FBV['fx'], V(TM_FB)), "'YOU SHALL SANCTIFY' AGAINST 'NO MAN SHALL SANCTIFY' UPHELD BY DIVIDING THE SPHERES — Mishnah Arakhin 8:7 inside the spine (124:4): you sanctify it for its VALUE, never for the altar (R. Yishmael — the two verses at the answer sheet, Arakhin 29a:20; sanctified by word though holy from birth, Nazir 4b:11); TEMURAH'S CELL ALREADY CARRIES 15:19 AS ITS IMPORT against 27:26 (temurah.consecrate('firstborn_for_value') by CALL: value_consecration_yes — 'the two verses: you SHALL sanctify and no man shall sanctify: R. Yishmael resolves them'); THE READBACK'S DISAGREES ROW 15:19 RESOLVED AS DATA (the row stays OPEN as the design wrote it, the resolution the parameter)")
        dat('THE WRITE firstling_sanctification_commanded — a STATUS on israel_people at the counter\'s day (DG2), its value THE PARAMETER the_sanctify_for_value (Arakhin 8:7 — the declaration a mitzvah, the value the Temple treasury\'s); the exam\'s person the owner who declares "this firstling is holy" — accepted, for its value')
        return out("sanctify for value (15:19) — 'you shall sanctify' against Leviticus 27:26's 'no man shall sanctify' upheld by dividing the spheres: for its value, never for the altar (the Sifrei 124:4; Mishnah Arakhin 8:7; Arakhin 29a:20; temurah.consecrate by CALL — value_consecration_yes): THE WRITE firstling_sanctification_commanded, a STATUS on Israel at the chapter's own day; the owner who declares 'this firstling is holy' accepted — for its value", ['firstling_sanctification_commanded'])
    if ask == 'the_altars_bar':
        ink('15:19', '"you shall sanctify to the LORD your God" — "to the LORD" at 15:2, 19, 21 %s; 27:26\'s "it is the LORD\'s" %s' % ([v for v in range(1, 24) if 'ליהוה' in W15(v)], words('Lev', 27, 26)[-2:]))
        move('the Sifrei 124:3-4 (read whole at the reading); Arakhin 29a:20 (read whole at the docket); cold_run_temurah (CALL) — TM.consecrate(firstborn) = %s, TM.firstborn_trick() = %s; cold_run_primeval (CALL) — PV.cain(firstling_by_call) = %s' % (V(TM_FB), V(TM_TRICK), V(PV_FIRSTLING)), "THE ALTAR'S BAR — 'no man shall sanctify it' (Leviticus 27:26 by CALL: cannot_be_sanctified_to_the_altar — the firstling is the LORD's already; the primeval runner already calling it for Abel's firstlings); THE CONSECRATED BY A REFUTED A FORTIORI THEN THE VERSE (124:3 — I1, checked in MIDDOT.md; 71:6's form): might the firstling be sanctified as another offering? the verse; the trick of the womb (temurah.firstborn_trick — 'what is in her womb, if male, an olah' before it is born a firstling)")
        dat('the altar\'s bar a DATA row (the_altars_bar — 27:26 by CALL; 124:3 the refuted a fortiori; the womb\'s trick); the exam\'s person the one who sanctifies the firstling as a burnt offering — barred from it')
        return out("the altar's bar (15:19) — 'no man shall sanctify it' (Leviticus 27:26 by CALL to temurah.consecrate — cannot be sanctified to the altar, it is the LORD's already); the consecrated by a refuted a fortiori then the verse (the Sifrei 124:3 — I1): the one who sanctifies the firstling as a burnt offering barred from it", ['barred_from_it'])
    if ask == 'the_caesarean':
        ink('15:19', '"every firstling that is BORN" — "born" %s; Exodus 13:2\'s "opener of the womb" %s' % ([x for x in W15(19) if x == 'יולד'], words('Exod', 13, 2)[4:6]))
        move('the Sifrei 124:2 (read whole at the reading); Mishnah Bekhorot 2:9 (read whole at the docket); Niddah 40a:14, Tosefta Bekhorot 3:2 (read whole at the docket); cold_run_ordinances (CALL) — OR.gifts(caesarean) = %s; cold_run_priesthood (CALL) — PR.blemish(beast_unfits_in_man) caesarean = %s' % (V(OR_CAES), V(PR_UNFITS).get('caesarean')), "THE CAESAREAN OUT — 'that is born': to the exclusion of the one born by the wall (124:2); Mishnah Bekhorot 2:9 the caesarean and the one born after it neither a firstling (the caesarean by I2 'birth'/'birth', Niddah 40a:14; Tosefta Bekhorot 3:2); the ordinances' cell by CALL (not consecrated — the Passover engine's predicate 'opener of the womb')")
