    if ask == 'the_your_two_ways':
        ink('15:20', '"before the LORD your God YOU shall eat it year by year … YOU AND YOUR HOUSEHOLD" — "you and your household" %s (14:26\'s twin); Numbers 18:18 gives the flesh to the priest %s; Onkelos "the people of your house"' % (P('אתה', 'וביתך', books=DT), words('Num', 18, 18)))
        move('the Sifrei 124:5-6 (read whole at the reading); Bekhorot 32b-33a (credited by address — firstborn_eaters); cold_run_korach (CALL) — KO.the_gifts(firstborn_eaters) = %s, (firstborn_portions) fx %s' % (str(V(KO_EATERS))[:70], KO_WINDOW[1]), "'YOUR' TWO WAYS A DISPUTE — 'you shall eat it': the owner's, or the priest's? (124:5 — 'you and your household' 14:26's twin; the firstling's flesh the priest's by Numbers 18:18 'their flesh shall be yours as the wave-breast' — korach.the_gifts(firstborn_eaters) by CALL: Beit Shammai priests only, Beit Hillel the blemished to any); THE TWO BARS CROSSED BY FOUR A FORTIORI ARGUMENTS AND THE TWO FILES READING THE CLOSING VERSE OPPOSITE WAYS (124:6 — a DISPUTE of the two files the_files_disagree, for the exam)")
        dat('THE PARAMETER the_your_two_ways (124:5 — the owner\'s or the priest\'s; the flesh the priest\'s by Numbers 18:18 by CALL); THE PARAMETER the_files_disagree (124:6 — the two files opposite ways); the exam\'s person the owner who eats the unblemished firstling\'s flesh — barred from it (the priest\'s by Numbers 18:18)')
        return out("'your' two ways (15:20) — 'you shall eat it, you and your household': the owner's or the priest's (the Sifrei 124:5); the flesh the priest's by Numbers 18:18 (korach.the_gifts by CALL); the two files reading the closing verse opposite ways (124:6): THE PARAMETERS the_your_two_ways, the_files_disagree; the owner who eats the unblemished firstling's flesh barred from it", ['barred_from_it'])
    if ask == 'the_work_and_the_shearing':
        ink('15:19', '"YOU SHALL DO NO WORK with the firstling of your ox NOR SHEAR the firstling of your flock" — "you shall do no work with the firstling of your ox" %s (one seat; 21:3\'s heifer "not worked" %s the twin); "shear" the verb\'s seats %s (this the book\'s one — Jacob\'s Laban, Judah\'s sheepshearers, Nabal\'s, Isaiah 53:7); the two negations at 15:19' % (P('לא', 'תעבד', 'בבכר', 'שורך'), P('לא', 'עבד', 'בה'), [s for s in GZZ if s.startswith(('Deut', 'Gen', '1Sam 25:2', 'Isa'))]))
        move('the Sifrei 124:6 (read whole at the reading); Bekhorot 9b:13, 24b:5, 41b:2 (read whole at the docket); Chullin 135a:9, 135b:13, 136b:18, 137a:4, Temurah 11b:15, Tosefta Bekhorot 1:6, 2:3 (read whole at the docket); cold_run_temurah (CALL) — TM.tithe(herd_with_flock) = %s' % (V(TM_HERD),), "THE WORK AND THE SHEARING A BLOCK — the two bars crossed by four a fortiori arguments and closed by the verse (124:6); 'your ox … your flock' the partnership's arm (Bekhorot 9b:13); the neck's hair plucked not shorn (24b:5; Mishnah 3:3); THE SANCTION GATED ON CERTAINTY (41b:2); the ban borrowed by the first shearing and read over both kinds (Chullin 135a:9-137a:4); the blemished consecrated's lashes (Tosefta Bekhorot 2:3 — with R. Shimon's arm 1:6); the herd's tithe 'under the rod' by CALL (temurah.tithe — not tithed together)")
        dat('THE WRITE firstling_work_and_shearing_barred — a BLOCK on israel_people at the counter\'s day (DG2); the exam\'s person the one who shears the firstling — barred from it (the lashes gated on certainty, 41b:2)')
        return out("the work and the shearing (15:19) — 'you shall do no work … nor shear': the two bars closed by the verse (the Sifrei 124:6); the partnership's arm, the sanction gated on certainty (Bekhorot 9b:13, 41b:2), the ban read over both kinds (Chullin 135a-137a): THE WRITE firstling_work_and_shearing_barred, a BLOCK on Israel at the chapter's own day; the one who shears the firstling barred from it", ['firstling_work_and_shearing_barred'])
    if ask == 'the_plucking':
        ink('15:19', '"nor SHEAR the firstling of your flock" — "shear" (גזז) the ban\'s verb %s; Onkelos "you shall not shear" (תגוז) one seat' % ([x for x in W15(19) if 'תגז' in x],))
        move('Bekhorot 25a:1-16 (read whole at the docket)', "PLUCKING IS NOT SHEARING — Rav (Bekhorot 25a:1-16): the cleaver's clearing by hand, not by a tool that looks like shearing (25a:13); plucked to show a blemish from the outset (25a:14-16); the red heifer's black-tipped hairs (25a:8-12): THE BAN'S DEFINITION A DATA ROW beside 15:19's block")
        dat('the plucking a DATA row (the_plucking — Bekhorot 25a:1-16: plucking is not shearing; by hand to show the blemish); the exam\'s person the one who plucks the firstling\'s hair by hand to show its blemish — accepted')
        return out("the plucking (15:19) — plucking is not shearing: the cleaver's clearing by hand, not by a tool that looks like shearing; plucked to show a blemish from the outset (Bekhorot 25a:1-16 — Rav): the one who plucks the firstling's hair by hand to show its blemish accepted", ['accepted'])
