    if ask == 'the_blemished_thirty_days':
        ink('15:20-21', '"you shall eat it year by year … and if there be any blemish in it" — the blemished after the year the Mishnah\'s thirty days; "blemish" twice at 15:21 %s' % ([x for x in W15(21) if x == 'מום'],))
        move('Mishnah Bekhorot 4:1-2 (read whole at the docket); Bekhorot 28a:3-4, 28a:7-11 (read whole at the docket); cold_run_korach (CALL) — KO.the_gifts(blemished_keeping) = %s, (blemished_firstborn) = %s' % (str(V(KO_KEEP))[:80], str(V(KO_BLEM))[:60]), "THE BLEMISHED THIRTY DAYS AFTER THE YEAR — Mishnah Bekhorot 4:1: the unblemished within its year, the blemished thirty days after (korach's cell by CALL: 'a blemish within the year — kept the twelve months; after the year — thirty days'); THE THIRTY DAYS FOR THE LOST ITEM'S RETURN (28a:7-9); R. Elazar's thirty-from-the-blemish CONCLUSIVELY REFUTED (28a:11 — 28a:10's link row the refuted arm); THE BLEMISHED GIVEN TO THE PRIEST from 'it shall be yours' and 'their flesh' (28a:3-4 — 'stated nowhere else in the Torah')")
        dat('the blemished thirty days a DATA row (the_blemished_thirty_days — Mishnah Bekhorot 4:1-2; 28a:7-11; R. Elazar\'s arm refuted); the exam\'s person the priest who keeps the blemished firstling beyond thirty days after its year — barred from it')
        return out("the blemished thirty days (15:20-21) — the blemished firstling thirty days after its year (Mishnah Bekhorot 4:1-2; Bekhorot 28a:7-9 the lost item's thirty; R. Elazar's thirty-from-the-blemish refuted 28a:11; korach.the_gifts by CALL); the blemished the priest's from 'it shall be yours' (28a:3-4): the priest who keeps the blemished firstling beyond thirty days after its year barred from it", ['barred_from_it'])
